@startuml

class Boeing {
  + CompanyName : string
}

class Airline {
  + Name : string
  + RegistrationNumber : string
}

class Employee {
  + Name : string
  + EmployeeID : string
}

class Salesperson {
  + SalesID : string
}

class Contract {
  + ContractID : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AcquisitionID : string
  + NegotiatedPrice : float
  + DeliveryDate : date
  + Options : string
}

class Airplane {
  + SerialNumber : string
  + Model : string
  + ManufactureDate : date
}

Employee "1" -- "0..*" Salesperson
Salesperson "1" -- "0..*" Contract
Airline "1" -- "0..*" Contract
Contract "1" *-- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "0..1" o-- "0..*" Airline : daughterOf

@enduml

